392:   if (~path.indexOf('\0')) return this.error(400);
393: 
394:   var parts
395:   if (root !== null) {
396:     // join / normalize from optional root dir
397:     path = normalize(join(root, path))
398: 
399:     // malicious path
400:     if (path.substr(0, root.length) !== root) {
401:       debug('malicious path "%s"', path)
402:       return this.error(403)
403:     }
404: 
405:     // explode path parts
406:     parts = path.substr(root.length + 1).split(sep)
407:   } else {
408:     // ".." is malicious without "root"
409:     if (upPathRegexp.test(path)) {
410:       debug('malicious path "%s"', path)
411:       return this.error(403)
412:     }
413: 
414:     // explode path parts
415:     parts = normalize(path).split(sep)
416: 
417:     // resolve the path
418:     path = resolve(path)
419:   }
420: 
421:   // dotfile handling
422:   if (containsDotFile(parts)) {
423:     var access = this._hidden
424:       ? 'allow'
425:       : 'ignore'
426: 
427:     debug('%s dotfile "%s"', access, path)
428:     switch (access) {
