430:         break
431:       case 'ignore':
432:       default:
433:         return this.error(404)
434:     }
435:   }
436: 
437:   // index file support
438:   if (this._index.length && this.hasTrailingSlash()) {
439:     this.sendIndex(path);
440:     return res;
441:   }
442: 
443:   debug('stat "%s"', path);
444:   fs.stat(path, function(err, stat){
