461: SendStream.prototype.send = function(path, stat){
462:   var options = this.options;
463:   var len = stat.size;
464:   var res = this.res;
465:   var req = this.req;
466:   var ranges = req.headers.range;
467:   var offset = options.start || 0;
468: 
469:   if (res._header) {
470:     // impossible to send now
471:     return this.headersAlreadySent();
472:   }
473: 
474:   debug('pipe "%s"', path)
475: 
476:   // set header fields
477:   this.setHeader(path, stat);
478: 
479:   // set content-type
480:   this.type(path);
481: 
482:   // conditional GET support
483:   if (this.isConditionalGET()
484:     && this.isCachable()
485:     && this.isFresh()) {
486:     return this.notModified();
487:   }
488: 
489:   // adjust len to start/end options
490:   len = Math.max(0, len - offset);
491:   if (options.end !== undefined) {
492:     var bytes = options.end - offset + 1;
493:     if (len > bytes) len = bytes;
494:   }
495: 
496:   // Range support
497:   if (ranges) {
498:     ranges = parseRange(len, ranges);
499: 
500:     // If-Range support
501:     if (!this.isRangeFresh()) {
502:       debug('range stale');
503:       ranges = -2;
504:     }
505: 
506:     // unsatisfiable
507:     if (-1 == ranges) {
508:       debug('range unsatisfiable');
509:       res.setHeader('Content-Range', 'bytes */' + stat.size);
510:       return this.error(416);
511:     }
512: 
513:     // valid (syntactically invalid/multiple ranges are treated as a regular response)
514:     if (-2 != ranges && ranges.length === 1) {
515:       debug('range %j', ranges);
516: 
517:       options.start = offset + ranges[0].start;
518:       options.end = offset + ranges[0].end;
519: 
520:       // Content-Range
521:       res.statusCode = 206;
522:       res.setHeader('Content-Range', 'bytes '
523:         + ranges[0].start
524:         + '-'
525:         + ranges[0].end
526:         + '/'
527:         + len);
528:       len = options.end - options.start + 1;
529:     }
530:   }
531: 
532:   // content-length
533:   res.setHeader('Content-Length', len);
534: 
535:   // HEAD support
536:   if ('HEAD' == req.method) return res.end();
537: 
538:   this.stream(path, options);
539: };
